fn my_string_4()
{
    println!("----- my_string_4 -----");
    let mut s0  = String::from("foo");
    let     s1  = String::from("bar");
    println!("0. s0 = {}", s0);
    s0.push_str(&s1); // push a string into the target string 's0'

    println!("1. s0 = {}", s0);
    println!("   s1 = {}", s1);

    let letter: char = '*';
    s0.push(letter); // push single letter string into the target string 's0'
    println!("2. s0 = {}", s0);
}

fn my_string_5()
{
    //
    // store string content with UTF-8 encoding
    //
    println!("----- my_string_5 -----");
    let hello_ary = [
        String::from("السلام عليكم"), // 0. right to left language characters
        String::from("Dobrý den"),
        String::from("Hello"),
        String::from("שָׁלוֹם"),        // 1. right to left language characters
        String::from("नमस्ते"),
        String::from("こんにちは"),
        String::from("안녕하세요"),
        String::from("你好"),
        String::from("Olá"),
        String::from("Здравствуйте"),
        String::from("Hola")
    ];

    let mut idx = 0;
    for s in hello_ary {
        println!("{}. \"{}\"", idx ,s);
        // ++idx; 
        idx += 1;
    }

}


