fn my_string_7()
{
    // push_str( "..." )
    // let end_str = String::from("Hello");
    // s.push_str(  &end_str ); // it is a borrowing
    // println!("s = {}, end_str = {}", s, end_str); // Compile [PASSED] , end_str can be used later
    println!("----- my_string_7 -----");
    let s1 = String::from("Hello");
    let s2 = String::from(" World");

    // take care of the    '+'   syntax
    let s3 = s1 + &s2; 
    // let s3 = s1 + " World";   // it also works as expected.

    /*

    println!("s1 = \"{}\"", s1);  // this line will raise a compile error

    Core Core Core :
    Because :
       s1 is not borrowed , it will be expired after the following statement :
       let s3 = s1 + &s2; // after that s1 has been dropped 

    */
    // println!("s1 = \"{}\"", s1);
    println!("s2 = \"{}\"", s2);
    println!("s3 = \"{}\"", s3);

    let s_1 = String::from("tic");
    let s_2 = String::from("tac");
    let s_3 = String::from("toe");

    let s_allv1 = s_1 + "-" + &s_2 + "-" + &s_3; // s_allv1 is a kind of String

    // either of the method works well.
    let s_11 = String::from("tic");
    // [ERROR] @ Compile time , because s1 has been expired already
    // let s_allv2 = format!("{}-{}-{}", s_1, s_2, s_3);
    let s_allv2 = format!("{}-{}-{}", s_11, s_2, s_3); // s_allv2 is a kind of String
    println!("s_allv1 = {}", s_allv1);
    println!("s_allv2 = {}", s_allv2);

}


/********************************************************************************************************************************
Rust 有三种看待字符串的方式:
1. bytes             : 字节       str_obj.bytes()
2. Scalar Values     : 标量值     str_obj.chars()
3. Grapheme Clusters : 字形簇(最接近所有"字母")   // you use call 3rd-party library , it's not a standard in Rust

********************************************************************************************************************************/
fn my_string_8()
{
    println!("----- my_string_8 -----");
    /********************************************************************************************************************************
     *                      Unicode 标量值
     *     Rust will pick every Unicode scalar value from the string
     * And calculate how many bytes are there in every unicode scalar value and summarize them in total
     *
     ********************************************************************************************************************************/
    // use    string_obj.len() =>  the bytes count in it.
    let str_ary: [String;4] = [
        // len#1 => yield 5 in bytes , because every chars occupy 1 byte
        String::from("Hello"),
        // len#2 => yield 4 in bytes , because every chars occupy 2 bytes
        String::from("𝓐𝓑"),
        // len#3 => yield 6 in bytes , because every chars occupy 3 bytes
        String::from("我们"),

        // chinese character '𠄘' looks like '承' , but they are two different things. 
        // 𠄘	U+20118 ,   "\xF0\xA0\x84\x98";
        // 承	U+627F  ,   "\xE6\x89\xBF";
        String::from("𠄘认"),    // 4 + 3 = 7
    ];

    let mut idx: i32 = 0;
    for words in str_ary {
        idx += 1;
        println!("{}. {} length = {}", idx, words, words.len() );
    }

    println!("Conclusion : ");
    println!("    !!! Not every character consists same-width bytes even if they belongs to the same language system !!!");
    println!("e.g. ");
    println!("      𠄘 consists 4 bytes. (UTF-8 encoding : F0 A0 84 98)");
    println!("      承 consists 3 bytes. (UTF-8 encoding : E6 89 BF)");
    println!("      认 consists 3 bytes. (UTF-8 encoding : E8 AE A4)");
    
}


